import { logger, DDBProxy, PatreonHelper, Secrets, DDBCampaigns, postJson } from "../lib/_module";
export default class DDBPartyInventory {
    static getCampaignId(notifier = null, override = null) {
        const campaignId = override ?? DDBCampaigns.getCampaignId(notifier);
        if (!campaignId || `${campaignId}`.trim() === "") {
            logger.error("No campaignId set; party inventory requires a campaign.");
            return "";
        }
        return `${campaignId}`;
    }
    static async fetchCampaignInfo({ cobalt = null, campaignId = null, } = {}) {
        const cobaltCookie = cobalt ?? Secrets.getCobalt();
        const parsingApi = DDBProxy.getProxy();
        const betaKey = PatreonHelper.getPatreonKey();
        const resolvedCampaignId = DDBPartyInventory.getCampaignId(null, campaignId);
        if (!resolvedCampaignId)
            return null;
        const body = {
            cobalt: cobaltCookie,
            betaKey,
            campaignId: resolvedCampaignId,
        };
        try {
            const data = await postJson(`${parsingApi}/proxy/party/${resolvedCampaignId}/characters`, body);
            if (!data.success) {
                logger.error(`Campaign characters fetch failed: ${data.message}`, data);
                return null;
            }
            // Backwards-compat: older proxies returned a bare characters array
            const payload = Array.isArray(data.data)
                ? { campaignId: parseInt(resolvedCampaignId), name: null, dmUsername: null, dmId: null, dateCreated: null, playerCount: data.data.length, characters: data.data }
                : data.data;
            if (payload?.rawCharacterSample || payload?.rawCampaignKeys) {
                logger.warn("DDBPartyInventory: proxy returned diagnostic payload (no characters extracted)", {
                    rawCampaignKeys: payload?.rawCampaignKeys,
                    rawCharacterSample: payload?.rawCharacterSample,
                });
            }
            const target = parseInt(resolvedCampaignId);
            const characters = (payload?.characters ?? []).filter((c) => {
                if (c?.campaignId === undefined || c?.campaignId === null)
                    return true;
                return parseInt(`${c.campaignId}`) === target;
            });
            return {
                campaignId: target,
                name: payload?.name ?? null,
                dmUsername: payload?.dmUsername ?? null,
                dmId: payload?.dmId ?? null,
                dateCreated: payload?.dateCreated ?? null,
                playerCount: payload?.playerCount ?? characters.length,
                characters,
            };
        }
        catch (error) {
            logger.error(`Campaign info fetch error: ${error}`);
            throw error;
        }
    }
    static async fetchCampaignCharacters({ cobalt = null, campaignId = null, } = {}) {
        const info = await DDBPartyInventory.fetchCampaignInfo({ cobalt, campaignId });
        return info?.characters ?? [];
    }
    static async fetchPartyInventory({ cobalt = null, campaignId = null, } = {}) {
        const cobaltCookie = cobalt ?? Secrets.getCobalt();
        const parsingApi = DDBProxy.getProxy();
        const betaKey = PatreonHelper.getPatreonKey();
        const resolvedCampaignId = DDBPartyInventory.getCampaignId(null, campaignId);
        if (!resolvedCampaignId)
            return null;
        const body = {
            cobalt: cobaltCookie,
            betaKey,
            campaignId: resolvedCampaignId,
        };
        try {
            const data = await postJson(`${parsingApi}/proxy/party/${resolvedCampaignId}/inventory`, body);
            if (!data.success) {
                logger.error(`Party inventory fetch failed: ${data.message}`, data);
                return null;
            }
            return data.data;
        }
        catch (error) {
            logger.error(`Party inventory fetch error: ${error}`);
            throw error;
        }
    }
    static PARTY_CONTAINER_ENTITY_TYPE_ID = 618115330;
    static async moveInventoryItem({ cobalt = null, characterId, id, containerEntityId, containerEntityTypeId = DDBPartyInventory.PARTY_CONTAINER_ENTITY_TYPE_ID, }) {
        const cobaltCookie = cobalt ?? Secrets.getCobalt();
        const parsingApi = DDBProxy.getProxy();
        const betaKey = PatreonHelper.getPatreonKey();
        const body = {
            cobalt: cobaltCookie,
            betaKey,
            characterId,
            id,
            containerEntityId,
            containerEntityTypeId,
        };
        try {
            const data = await postJson(`${parsingApi}/proxy/inventory/item/move`, body, { method: "PUT" });
            if (!data.success) {
                logger.error(`Inventory item move failed: ${data.message}`, data);
                return null;
            }
            return data.data;
        }
        catch (error) {
            logger.error(`Inventory item move error: ${error}`);
            throw error;
        }
    }
    static async moveItemToParty({ cobalt = null, characterId, id, campaignId, }) {
        return DDBPartyInventory.moveInventoryItem({
            cobalt,
            characterId,
            id,
            containerEntityId: campaignId,
            containerEntityTypeId: DDBPartyInventory.PARTY_CONTAINER_ENTITY_TYPE_ID,
        });
    }
    static async deleteInventoryItem({ cobalt = null, characterId, id, removeContainerContents = false, campaignId = null, }) {
        const cobaltCookie = cobalt ?? Secrets.getCobalt();
        const parsingApi = DDBProxy.getProxy();
        const betaKey = PatreonHelper.getPatreonKey();
        const body = {
            cobalt: cobaltCookie,
            betaKey,
            characterId,
            id,
            removeContainerContents,
            campaignId,
        };
        try {
            const data = await postJson(`${parsingApi}/proxy/inventory/item`, body, { method: "DELETE" });
            if (!data.success) {
                logger.error(`Inventory item delete failed: ${data.message}`, data);
                return null;
            }
            return data.data;
        }
        catch (error) {
            logger.error(`Inventory item delete error: ${error}`);
            throw error;
        }
    }
}
