import { SETTINGS } from "../config/_module";
import utils from "./Utils";
const DDBProxy = {
    isCustom: (orDev = false) => {
        if (orDev && CONFIG.DDBI.DEV.enabled)
            return false;
        return utils.getSetting("custom-proxy");
    },
    resetProxy: () => {
        game.settings.set(SETTINGS.MODULE_ID, "api-endpoint", SETTINGS.DEFAULT_SETTINGS.READY.PROXY["api-endpoint"].default);
        game.settings.set(SETTINGS.MODULE_ID, "custom-proxy", false);
    },
    getProxy: () => {
        if (DDBProxy.isCustom() || CONFIG.DDBI.DEV.enabled)
            return utils.getSetting("api-endpoint");
        else
            return SETTINGS.URLS.PROXY;
    },
    getDynamicProxy: () => {
        if (CONFIG.DDBI.DEV.enabled)
            return utils.getSetting("dynamic-api-endpoint");
        else
            return SETTINGS.URLS.DYNAMIC;
    },
    getCORSProxy: () => {
        if (DDBProxy.isCustom() || CONFIG.DDBI.DEV.enabled || CONFIG.DDBI.DEV.customCors)
            return utils.getSetting("cors-endpoint");
        return SETTINGS.URLS.CORS;
    },
};
export default DDBProxy;
