import DDBEnricherData from "../data/DDBEnricherData";
export default class EnsnaringStrike extends DDBEnricherData {
    get type() {
        return this.is2014 && this.useMidiAutomations ? DDBEnricherData.ACTIVITY_TYPES.UTILITY : DDBEnricherData.ACTIVITY_TYPES.NONE;
    }
    get activity() {
        return {
            name: "Cast (Automation)",
        };
    }
    get clearAutoEffects() {
        return true;
    }
    get additionalActivities() {
        return [
            {
                init: {
                    name: "Save vs Restrained",
                    type: DDBEnricherData.ACTIVITY_TYPES.SAVE,
                },
                build: {
                    generateSave: true,
                    generateActivation: true,
                    generateConsumption: false,
                    generateDamage: false,
                    generateTarget: true,
                },
                overrides: {
                    targetType: "creature",
                    activationType: "special",
                    noSpellslot: this.useMidiAutomations,
                },
            },
            {
                init: {
                    name: "Damage",
                    type: DDBEnricherData.ACTIVITY_TYPES.DAMAGE,
                },
                build: {
                    generateDamage: true,
                    generateConsumption: false,
                    noSpellslot: true,
                    generateAttack: false,
                    onsave: false,
                    damageParts: [
                        DDBEnricherData.basicDamagePart({
                            number: 1,
                            denomination: 6,
                            types: ["piercing"],
                            scalingMode: "whole",
                            scalingNumber: 1,
                        }),
                    ],
                    noeffect: true,
                },
                overrides: {
                    noTemplate: true,
                    activationType: "special",
                    activationCondition: "Start of Targets Turn",
                },
            },
        ];
    }
    get effects() {
        const automationEffects = this.is2014
            ? [
                {
                    name: `${this.data.name} (Automation)`,
                    activityMatch: "Cast (Automation)",
                    midiOnly: true,
                    midiChanges: [
                        DDBEnricherData.ChangeHelper.unsignedAddChange("@spellLevel", 20, "flags.midi-qol.ensnaringStrike.level"),
                    ],
                    onUseMacroChanges: [
                        { macroPass: "postActiveEffects", macroType: "spell", macroName: "ensnaringStrike.js", document: this.data },
                    ],
                    data: {
                        flags: {
                            dae: {
                                specialDuration: [],
                                selfTargetAlways: true,
                                selfTarget: true,
                            },
                        },
                    },
                },
            ]
            : [];
        return [
            {
                name: `${this.data.name}: Restrained`,
                statuses: ["Restrained"],
                activityMatch: "Save vs Restrained",
                midiChanges: [
                    DDBEnricherData.ChangeHelper.customChange(`turn=start,damageRoll=(@spellLevel)d6,damageType=piercing,label=${this.data.name}: Entangled,actionSave=roll,rollType=check,saveAbility=str,saveDC=@attributes.spell.dc,killAnim=true`, 20, "flags.midi-qol.OverTime"),
                ],
            },
            ...automationEffects,
        ];
    }
    get itemMacro() {
        if (!this.is2014)
            return null;
        return {
            type: "spell",
            name: "ensnaringStrike.js",
        };
    }
}
